create table veranolink.vl_source_applications (
    id_vl_source_application number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment
    by 1 cache 20 noorder nocycle nokeep noscale not null enable,
    name                     varchar2(50 char),
    alias                    varchar2(10 char),
    vl_application_img       varchar2(100 byte)
);

alter table veranolink.vl_source_applications
    add constraint vl_source_applications_pk primary key ( id_vl_source_application )
        using index enable;

